import{_ as o,o as t,c as d,ag as a}from"./chunks/framework.BaNuf0sO.js";const h=JSON.parse('{"title":"components 组件族总引导","description":"","frontmatter":{},"headers":[],"relativePath":"docs/core/src/components/README.md","filePath":"docs/core/src/components/README.md"}'),c={name:"docs/core/src/components/README.md"};function r(l,e,n,s,i,m){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="components-组件族总引导" tabindex="-1">components 组件族总引导 <a class="header-anchor" href="#components-组件族总引导" aria-label="Permalink to &quot;components 组件族总引导&quot;">​</a></h1><p>core 共 12 个组件族，全部经顶层 barrel 导出（<code>import { FormMain } from &quot;@done-coding/admin-core&quot;</code>）。各族目录内均有 <code>README.md</code> 入口（组件清单 + 指向 <code>docs/</code> 组件详情文档，<code>README-&lt;PascalName&gt;.md</code>）。</p><p><strong>页面范式</strong>：<code>AppPage</code>（页面容器）→ <code>ListLayout</code>（列表）/ <code>FormMain</code>（表单）/ <code>ViewLayout</code>（展示）→ <code>TableMain</code> / <code>FormSearch</code> 子配置。⚠️ 存量 <code>PanelMain</code> 的页级展示一等公民地位已撤销、将废弃——新页面 [MUST NOT] 以 PanelMain 作页级展示根容器（详见 panel 族文档）。</p><h2 id="配置化体系契约-设计引导" tabindex="-1">配置化体系契约（设计引导） <a class="header-anchor" href="#配置化体系契约-设计引导" aria-label="Permalink to &quot;配置化体系契约（设计引导）&quot;">​</a></h2><blockquote><p>提炼自配置化体系设计范式（2026-08 对照 MIGRATION 与源码验证时效）。开发/接入前 [MUST] 先读本节。</p></blockquote><h3 id="第一性原理" tabindex="-1">第一性原理 <a class="header-anchor" href="#第一性原理" aria-label="Permalink to &quot;第一性原理&quot;">​</a></h3><ul><li><strong>万物皆表单项</strong>：任何输入形态（upload / JSON / 选择器 / 验证码…）都是 <code>FormItemConfig</code> 的 render/component 变体——[MUST NOT] 另造「输入组件」形态</li><li><strong>万物皆 Nest 递归组合</strong>：嵌套子表单/子面板不手写 HTML，走 <code>nestFormItem</code> / <code>nestFormItemList</code> / <code>nestPanelItem</code> / <code>nestPanelForm</code>（配置一个容器的产物本身又是合法 item 内容，跨等级递归自嵌套）</li><li><strong>编排即组合、不是分类</strong>：customView 是列表视图变体不单列一类；横排/竖排/分步同源不为布局差异另造范式——组合自由、非封闭模板</li><li><strong>容器即 prop</strong>：弹窗/抽屉一个 <code>layerType</code> 切、大小一个 <code>width</code> 切——不另造形态</li></ul><h3 id="空间一等公民-组合件优先" tabindex="-1">空间一等公民（组合件优先） <a class="header-anchor" href="#空间一等公民-组合件优先" aria-label="Permalink to &quot;空间一等公民（组合件优先）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>空间</th><th>一等公民（优先用）</th><th>零件（底层，一般经一等公民使用）</th></tr></thead><tbody><tr><td>列表</td><td><code>ListLayout</code></td><td><code>TableMain</code>（表格侧）/ <code>FormSearch</code>（搜索侧）</td></tr><tr><td>纯表单提交</td><td><code>FormSubmitPanel</code></td><td><code>FormMain</code>（底座）/ <code>FormSubmitBtn</code></td></tr><tr><td>弹窗 CRUD / 表单</td><td><code>ModalDetail</code> / <code>ModalForm</code></td><td><code>ModalConfirm</code>（原语底座）</td></tr><tr><td>弹窗命令式</td><td><code>ModalPorter</code> + <code>ModalShelf</code>（app/page 内置）</td><td>—</td></tr><tr><td>展示</td><td><code>ViewLayout</code></td><td><code>PanelMain</code>（将废弃，仅表单预览 / 就地编辑保留）<code>PanelItem</code> / <code>PanelEditSwitch</code></td></tr><tr><td>多 tab</td><td><code>TabsMain</code></td><td><code>TabsRefineFlow</code> 等（内部件）</td></tr></tbody></table><p>业务层 [MUST] 一等公民优先：能用 <code>TableMain</code> 处用 <code>ListLayout</code>、能用 <code>FormMain</code> 处用 <code>FormSubmitPanel</code>；裸用仅限特例（详见各族文档定位段断言）。</p><h3 id="配置化字段归位四机制" tabindex="-1">配置化字段归位四机制 <a class="header-anchor" href="#配置化字段归位四机制" aria-label="Permalink to &quot;配置化字段归位四机制&quot;">​</a></h3><p><code>ignore</code>（视图在数据不在）/ <code>hide</code>（数据在视图不在）/ <code>staticQuery</code>（列表查询固定参数）/ <code>init</code>（可被用户覆盖的初值）——字段落位先按四机制归位，[MUST NOT] 硬编码过滤。</p><h3 id="弹窗即空间" tabindex="-1">弹窗即空间 <a class="header-anchor" href="#弹窗即空间" aria-label="Permalink to &quot;弹窗即空间&quot;">​</a></h3><ul><li>内容型弹窗 [MUST] 走 <code>modalList</code> item + <code>shelf:&quot;page&quot;</code> + <code>ModalPorter.evoke(key, payload)</code>；[MUST NOT] 直挂 <code>ModalDetail</code>/<code>ModalForm</code> 组件到页面、[MUST NOT] 自声明 app/page 级 <code>ModalShelf</code>（AppLayout/AppPage 已内置）</li><li>确认类弹窗 [MUST NOT] 注册进 modalList：一句话确认走 <code>ActionBtn.confirmConfig</code>（popconfirm / messageConfirm）</li></ul><h3 id="页面反模式红线" tabindex="-1">页面反模式红线 <a class="header-anchor" href="#页面反模式红线" aria-label="Permalink to &quot;页面反模式红线&quot;">​</a></h3><ul><li>所有业务页面 [MUST] <code>AppPage</code> 包裹（自带 page 级 ModalShelf + 视口高度链）</li><li>单向数据流：[MUST NOT] 跨层/跨 tab 全局 store 通信（props / emit / payload 回调）</li><li>keepAlive 页返回刷新 core 内置（onActivated refresh 留页码），app 侧 [MUST NOT] 补偿（双重请求反模式）</li><li>新增按钮 [MUST] 走 <code>toolbar.leftExtraButtons</code>（ActionBtn 配置驱动）；操作列 [MUST] 用 <code>column.render</code> 工厂 + <code>ActionBtnGroup</code>（<code>#table-OPERATE</code> 槽已非推荐通道）</li><li>跨包纪律：桶级导出 / <code>Symbol.for</code> / 双链验证 / style.css 显式导入 / <code>ActionBtn</code> 替代 ElButton（细则见项目 CLAUDE.md 规则 6–11）</li><li>app 层范式：<code>useSpaceConfig</code> 单一配置出口 + handlers 出界注入（config 不 import router/不持 ref）——见 <code>apps/reference/src/pages/_shared/space.ts</code></li></ul><h2 id="族清单" tabindex="-1">族清单 <a class="header-anchor" href="#族清单" aria-label="Permalink to &quot;族清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>族</th><th>组件</th><th>入口</th></tr></thead><tbody><tr><td>form 表单族</td><td>FormMain / FormSearch / FormSubmitBtn / FormSubmitPanel / FormItemNestForm / FormItemNestFormList / FormSelect / FormRadioGroup / FormTree / FormVerifyImage / FormVerifyCode</td><td><a href="/done-coding-showcase/docs/core/src/components/form/README.html">README</a></td></tr><tr><td>list-layout 列表族</td><td>ListLayout（FormSearch + TableMain 组合页）</td><td><a href="/done-coding-showcase/docs/core/src/components/list-layout/README.html">README</a></td></tr><tr><td>table 表格族</td><td>TableMain</td><td><a href="/done-coding-showcase/docs/core/src/components/table/README.html">README</a></td></tr><tr><td>modal 弹窗族</td><td>ModalConfirm / ModalForm / ModalDetail / ModalShelf / ModalPorter</td><td><a href="/done-coding-showcase/docs/core/src/components/modal/README.html">README</a></td></tr><tr><td>panel 面板族</td><td>PanelMain / PanelItem / PanelEditSwitch / PanelItemNestPanel / PanelItemNestForm</td><td><a href="/done-coding-showcase/docs/core/src/components/panel/README.html">README</a></td></tr><tr><td>display 展示族</td><td>TabsMain / ActionBtn / ActionBtnGroup / ActionConfirm / WatchSize / HeightProvider / BooleanTag</td><td><a href="/done-coding-showcase/docs/core/src/components/display/README.html">README</a></td></tr><tr><td>app-layout 布局族</td><td>AppLayout / AppPage / AppBody / AppHeader / AppSidebar / AppAside / AppBreadcrumb / AppFooter / AppTheme / AppCollapseToggle（未导出）</td><td><a href="/done-coding-showcase/docs/core/src/components/app-layout/README.html">README</a></td></tr><tr><td>menu 菜单族</td><td>MenuTree / MenuItemSub</td><td><a href="/done-coding-showcase/docs/core/src/components/menu/README.html">README</a></td></tr><tr><td>slot-layout 插槽布局族</td><td>SlotLayoutTemplate / SlotLayoutFlowAside</td><td><a href="/done-coding-showcase/docs/core/src/components/slot-layout/README.html">README</a></td></tr><tr><td>view-layout 展示布局族</td><td>ViewLayout</td><td><a href="/done-coding-showcase/docs/core/src/components/view-layout/README.html">README</a></td></tr><tr><td>data-view 数据视图族</td><td>DataListView / DataListViewItem（TableMain 内部件，customView 模式；不进顶层 export）</td><td><a href="/done-coding-showcase/docs/core/src/components/data-view/README.html">README</a></td></tr><tr><td>misc 杂项族</td><td>AutoRefresh / AutoRefreshGroup / SelectModule / TriggerAutoImport（@deprecated）</td><td><a href="/done-coding-showcase/docs/core/src/components/misc/README.html">README</a></td></tr></tbody></table><h2 id="写作与维护约定" tabindex="-1">写作与维护约定 <a class="header-anchor" href="#写作与维护约定" aria-label="Permalink to &quot;写作与维护约定&quot;">​</a></h2><ul><li>各族 <code>README.md</code> = 入口（组件清单 + 一句话），组件详情在 <code>docs/README-&lt;PascalName&gt;.md</code></li><li><strong>快速上手 = 最小可用形态</strong>（默认值即够用，5–20 行可直接抄的代码）——[MUST NOT] 把能力全开示例当快速上手（AI 会按示例最大化使用，全能力示例反而误导）</li><li><strong>空间一等公民断言</strong>：组合件（ListLayout / FormSearch / FormSubmitPanel / ModalDetail 等）与零件（TableMain / FormMain / ModalConfirm / PanelItem 等）的文档 [MUST] 在定位段断言「优先经 &lt;空间组件&gt; 使用 + 直接使用仅当 &lt;特例&gt;」——配置化体系「空间一等公民优先」范式，[MUST NOT] 让 AI 把零件当默认起点。⚠️ <code>PanelMain</code> 已撤销一等公民地位（将废弃，已由 <code>ViewLayout</code> 承接），文档 [MUST NOT] 再以 PanelMain 作详情展示组合件示例</li><li><strong>每篇必含「能力边界 / 按需使用」段</strong>（快速上手之后）：逐条断言「默认关/默认即够用 + 仅当 X 场景才开（判据）」，末行给「完整能力演示」reference 指针——全能力代码不复制进文档正文（活代码在 reference showcase 页，零重复维护）</li><li>新增/改造对外组件 [MUST] 同步补 <code>docs/README-&lt;PascalName&gt;.md</code>（随 <code>docs/specs/</code> 任务闭环）</li><li>API 段以 <code>types.ts</code> + 组件源码为真相源；与文档冲突时以源码为准</li><li>内部件（不导出）<strong>也写独立文档，但仅 API 段</strong>（props/emits/slots/expose + 机制契约真相，以源码为真相源）——[MUST NOT] 写定位 / 快速上手 / 基础应用等消费向叙事段（无对外使用场景，写了反而误导 AI 当公共组件用）；族入口标注「内部件 · 仅 API」</li></ul><h3 id="开发流程-api-契约先行" tabindex="-1">开发流程（API 契约先行） <a class="header-anchor" href="#开发流程-api-契约先行" aria-label="Permalink to &quot;开发流程（API 契约先行）&quot;">​</a></h3><p>新组件 / 组件改造（含 API 变更）[MUST] 按四步走，[MUST NOT] 先实现后补文档：</p><ol><li><strong>API 契约先行</strong>：先写 <code>types.ts</code>（props/emits 类型）并<strong>同步更新</strong>对应 <code>docs/README-&lt;PascalName&gt;.md</code> 的 API 段（props/emits/slots/expose 表）——API 表先于实现存在、锁定契约；同时补「类型测试」锚（types.ts 形态断言——文档先行里唯一可执行的部分，把契约落成机器可验）</li><li><strong>实现</strong>：满足契约；实现中 API 微调属正常，同步回改 API 表（文档是承诺不是枷锁，但 [MUST NOT] 实现完成时 API 表与 types.ts 不一致）</li><li><strong>验收</strong>：reference 更新 demo（规则 10：范式页 + 手验 + build 静态验证）+ 单测 + 双链 build（规则 9.1）</li><li><strong>非 API 文档收尾</strong>（[MUST] 作为 spec TASK 单列，[MUST NOT] 靠「收尾顺手补」）：定位 / 快速上手（最小可用，从 demo 最小形态提炼）/ 能力边界 / 反模式——此时实现与 demo 已定型，写出的姿势全部经实证</li></ol><p><strong>复核闸</strong>：第 4 步执行时 [MUST] 对照 <code>types.ts</code> + <code>withDefaults</code> 复核 API 表（预言 vs 兑现兑平）——「API 以 types.ts 为真相源」双向执行：实现前 API 表当契约写，实现后 types.ts 当真相校。</p>',24)])])}const M=o(c,[["render",r]]);export{h as __pageData,M as default};
